contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Test: depositing `amount` never reduces the contract's recorded balance for this caller
    // and never reduces the contract's Ether balance.
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // observe before-values
        uint256 beforeRecorded = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeCbal = address(c).balance;

        // perform the deposit sending exactly `amount`
        bool reverted;
        c.addToBalance{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after-values
        uint256 afterRecorded = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterCbal = address(c).balance;

        // General rule: if the call did not revert then the recorded balance for this caller did not decrease
        // (afterRecorded >= beforeRecorded) and the contract's Ether balance did not decrease (afterCbal >= beforeCbal).
        // If the call reverted, state is unchanged from c's perspective, so both comparisons should still hold.
        assert(afterRecorded >= beforeRecorded && afterCbal >= beforeCbal);
    }

    // allow receiving Ether when c.withdrawBalance sends funds back
    receive() external payable {}
}

